css:
:scope{--brown:#472d1e;--ink:var(--os-color-text);--serif:'Cormorant Garamond',Georgia,serif;--sans:'Hanken Grotesk',system-ui,sans-serif;--gap:clamp(56px,9vw,120px)}
:scope{color:var(--ink);font-family:var(--sans);font-size:17px;line-height:1.7}
.t-table{display:table;border-collapse:collapse}
.t-thead{display:table-header-group}
.t-tr{display:table-row}
.t-th{display:table-cell;padding:1px;font-weight:bold;text-align:center}
.t-tbody{display:table-row-group}
.t-td{display:table-cell;padding:1px}
:where(h1,h2,h3,h4,h5,h6){color:inherit;font-family:inherit;font-weight:bold;font-style:inherit;letter-spacing:normal;text-transform:none;line-height:inherit;text-wrap:wrap}
:where(h1){font-size:2em}:where(h2){font-size:1.5em}:where(h3){font-size:1.17em}:where(h4){font-size:1em}:where(h5){font-size:.83em}:where(h6){font-size:.67em}
:where(.os-ci){display:inline-block;max-width:100%;vertical-align:middle;aspect-ratio:auto}
.os-ci>picture{display:contents}
.os-ci img{display:block;width:100%;height:100%;object-fit:inherit;object-position:inherit;border-radius:inherit}
*{box-sizing:border-box}
h2{font-family:var(--serif);color:var(--brown);font-weight:500;line-height:1.15;margin:0 0 .5em}
h2{font-size:clamp(2rem,4.5vw,3.1rem)}
p{margin:0 0 1.1em;max-width:62ch}
.wrap{max-width:1080px;margin:0 auto;padding:0 24px}
section{padding:var(--gap) 0}
.threads{width:100%;border-collapse:collapse;margin-top:1.6em}
.threads [class~="t-th"],.threads [class~="t-td"]{text-align:left;padding:14px 12px;border-bottom:1px solid #e3d6bd;vertical-align:top}
.threads [class~="t-td"]:first-child{font-family:var(--serif);font-size:1.3rem;color:var(--brown);white-space:nowrap}
@media (max-width:720px){.threads [class~="t-td"]:first-child{white-space:normal}}
@media (max-width:720px){.threads,.threads [class~="t-tbody"],.threads [class~="t-tr"],.threads [class~="t-td"],.threads [class~="t-th"]{display:block}}
@media (max-width:720px){.threads [class~="t-thead"]{display:none}}
@media (max-width:720px){.threads [class~="t-tr"]{padding:10px 0;border-bottom:1px solid #e3d6bd}}
@media (max-width:720px){.threads [class~="t-td"]{border:0;padding:2px 0}}
